/**
 * 扫描 PDF：页级流水线 = 渲一页 → 立刻 emit(layout+OCR) → 落账。
 * 多页有限并发；不先等全书渲染完再统一 OCR。
 */

import type { PageDocument, ResolvedConnection } from '../zigzag/types'
import type { OcrPageResult } from './ocrService'
import { imageUrlToDataUri } from './ocrService'
import {
  openPdfDocument,
  renderPdfPageDocument,
  type OpenedPdf,
} from './pdfImport'
import { emitPageViaProtocol } from '../reasoning/emitClient'
import { runBatchesParallel } from '../arch/parallelLlmBatch'

export const PDF_EMIT_CONCURRENCY = 3

export type PageEmitProgress = {
  done: number
  total: number
  strand: number
  phase: 'render_emit' | 'done'
  message: string
}

export async function ingestScannedPdfParallel(input: {
  file: File
  docId: string
  concurrency?: number
  onProgress?: (p: PageEmitProgress) => void
  /** 每完成一页：写入 pages / ocr（调用方可边收边挂球） */
  onPage?: (page: PageDocument, ocr: OcrPageResult) => void
}): Promise<{
  pages: PageDocument[]
  connections: ResolvedConnection[]
  label: string
  ocrByStrand: Record<number, OcrPageResult>
  done: number
  failed: number
  opened: OpenedPdf
}> {
  const opened = await openPdfDocument(input.file, (msg) => {
    input.onProgress?.({
      done: 0,
      total: 0,
      strand: 0,
      phase: 'render_emit',
      message: msg,
    })
  })
  const { doc, total, label } = opened
  const concurrency = Math.max(1, input.concurrency ?? PDF_EMIT_CONCURRENCY)
  const pageNums = Array.from({ length: total }, (_, i) => i + 1)

  const pagesSlot: Array<PageDocument | undefined> = Array.from({
    length: total,
  })
  const ocrByStrand: Record<number, OcrPageResult> = {}
  let done = 0
  let failed = 0
  let finished = 0

  const parallel = await runBatchesParallel({
    batches: pageNums,
    concurrency,
    run: async (pageNum) => {
      const page = await renderPdfPageDocument({
        doc,
        pageNumber: pageNum,
        label,
        totalPages: total,
      })
      if (!page.imageUrl) {
        throw new Error(`页 ${pageNum} 无图像`)
      }
      const dataUri = await imageUrlToDataUri(page.imageUrl)
      const ocr = await emitPageViaProtocol({
        docId: input.docId,
        page: page.strandIndex,
        strandIndex: page.strandIndex,
        imageDataUri: dataUri,
      })
      return { page, ocr }
    },
  })

  for (const r of parallel.results) {
    finished += 1
    if (r.ok) {
      const { page, ocr } = r.value
      pagesSlot[page.strandIndex] = page
      ocrByStrand[page.strandIndex] = ocr
      done += 1
      input.onPage?.(page, ocr)
      input.onProgress?.({
        done: finished,
        total,
        strand: page.strandIndex,
        phase: 'render_emit',
        message: `并行渲+OCR ${finished}/${total}（完成 ${done} · 失败 ${failed}）`,
      })
    } else {
      failed += 1
      const strand = typeof r.index === 'number' ? r.index : finished - 1
      // 占位页，避免球缺槽
      const placeholder: PageDocument = {
        strandIndex: strand,
        title: `${label} p.${strand + 1}（识别失败）`,
        text: `${label}\nPage ${strand + 1}\n(emit failed)`,
        offsetMap: [],
        sourceDoc: 'upload',
        sourcePage: strand + 1,
        textChunks: [],
      }
      if (!pagesSlot[strand]) pagesSlot[strand] = placeholder
      input.onProgress?.({
        done: finished,
        total,
        strand,
        phase: 'render_emit',
        message: `并行渲+OCR ${finished}/${total}（完成 ${done} · 失败 ${failed}）`,
      })
    }
  }

  // 补齐任何空槽
  for (let i = 0; i < total; i++) {
    if (!pagesSlot[i]) {
      pagesSlot[i] = {
        strandIndex: i,
        title: `${label} p.${i + 1}（缺失）`,
        text: `${label}\nPage ${i + 1}`,
        offsetMap: [],
        sourceDoc: 'upload',
        sourcePage: i + 1,
        textChunks: [],
      }
    }
  }

  input.onProgress?.({
    done: total,
    total,
    strand: Math.max(0, total - 1),
    phase: 'done',
    message: `全书处理完毕 · 成功 ${done}/${total}`,
  })

  return {
    pages: pagesSlot as PageDocument[],
    connections: [],
    label,
    ocrByStrand,
    done,
    failed,
    opened,
  }
}

/**
 * Browser-side PDF → page image cards (works for scanned PDFs).
 * Uses pdf.js *legacy* build so older Chromium/Safari without
 * Map.getOrInsertComputed still work (worker included).
 *
 * 全书可导入（不再硬截 80）。扫描路径请走 pdfPagePipeline：
 * 渲一页 → 立刻 emit，多页并行；勿先整本预渲再串行 OCR。
 */

import { ensurePdfRuntimePolyfills } from './pdfPolyfills'

ensurePdfRuntimePolyfills()

import * as pdfjs from 'pdfjs-dist/legacy/build/pdf.mjs'
import pdfWorker from './pdfWorkerBootstrap?worker&url'
import type { PageDocument, ResolvedConnection } from '../zigzag/types'
import { extractPdfTextChunks } from './pdfTextLayer'

pdfjs.GlobalWorkerOptions.workerSrc = pdfWorker

export type PdfjsDocument = Awaited<
  ReturnType<typeof pdfjs.getDocument>['promise']
>

export interface OpenedPdf {
  doc: PdfjsDocument
  total: number
  label: string
  fileName: string
}

export interface PdfImportProgress {
  phase: 'loading' | 'rendering' | 'done' | 'error'
  current: number
  total: number
  message: string
}

function canvasToObjectUrl(canvas: HTMLCanvasElement): Promise<string> {
  return new Promise((resolve, reject) => {
    canvas.toBlob(
      (blob) => {
        if (!blob) {
          reject(new Error('无法导出页面图像'))
          return
        }
        resolve(URL.createObjectURL(blob))
      },
      'image/jpeg',
      0.82,
    )
  })
}

function yieldToUi(): Promise<void> {
  return new Promise((resolve) => {
    window.setTimeout(resolve, 0)
  })
}

export async function openPdfDocument(
  file: File,
  onMessage?: (msg: string) => void,
): Promise<OpenedPdf> {
  const label = file.name.replace(/\.pdf$/i, '') || 'Uploaded PDF'
  onMessage?.(`读取 ${file.name}…`)
  const data = new Uint8Array(await file.arrayBuffer())
  const doc = await pdfjs.getDocument({
    data,
    wasmUrl: '/pdfjs-wasm/',
    useSystemFonts: true,
    disableFontFace: true,
  }).promise
  const total = doc.numPages
  if (total < 1) {
    throw new Error('PDF 没有可渲染的页面')
  }
  return { doc, total, label, fileName: file.name }
}

/** 单页渲染（原分辨率策略：短边目标宽约 960） */
export async function renderPdfPageDocument(input: {
  doc: PdfjsDocument
  /** 1-based pdf.js page number */
  pageNumber: number
  label: string
  totalPages: number
}): Promise<PageDocument> {
  const { doc, pageNumber, label, totalPages } = input
  const i = pageNumber
  await yieldToUi()

  const page = await doc.getPage(i)
  const base = page.getViewport({ scale: 1 })
  const targetW = 960
  const scale = Math.min(1.8, targetW / base.width)
  const viewport = page.getViewport({ scale })

  const canvas = document.createElement('canvas')
  canvas.width = Math.floor(viewport.width)
  canvas.height = Math.floor(viewport.height)
  const ctx = canvas.getContext('2d', { alpha: false })
  if (!ctx) throw new Error('Canvas 不可用')
  ctx.fillStyle = '#ffffff'
  ctx.fillRect(0, 0, canvas.width, canvas.height)

  const task = page.render({
    canvas,
    canvasContext: ctx,
    viewport,
    background: '#ffffff',
  })
  try {
    await task.promise
  } catch (err) {
    console.warn(`PDF page ${i} render failed`, err)
    canvas.width = 0
    canvas.height = 0
    return {
      strandIndex: i - 1,
      title: `${label} p.${i}（渲染失败）`,
      text: `${label}\nPage ${i} of ${totalPages}\n(render failed)`,
      offsetMap: [],
      sourceDoc: 'upload',
      sourcePage: i,
      textChunks: [],
    }
  }

  const imageUrl = await canvasToObjectUrl(canvas)
  canvas.width = 0
  canvas.height = 0

  const textChunks = await extractPdfTextChunks(page, viewport, i - 1)
  const extracted = textChunks
    .map((c) => c.content)
    .filter((t) => t.length > 0)
    .join('\n\n')

  return {
    strandIndex: i - 1,
    title: `${label} p.${i}`,
    text: extracted || `${label}\nPage ${i} of ${totalPages}`,
    offsetMap: [],
    imageUrl,
    sourceDoc: 'upload',
    sourcePage: i,
    textChunks,
  }
}

/**
 * 文字层路径：顺序渲完全书（保留图供球显示）。
 * 扫描 OCR 请用 ingestScannedPdfParallel，勿先走本函数再串行 OCR。
 */
export async function importPdfFile(
  file: File,
  onProgress?: (p: PdfImportProgress) => void,
): Promise<{
  pages: PageDocument[]
  connections: ResolvedConnection[]
  label: string
}> {
  const opened = await openPdfDocument(file, (message) => {
    onProgress?.({
      phase: 'loading',
      current: 0,
      total: 0,
      message,
    })
  })
  const { doc, total, label } = opened

  const pages: PageDocument[] = []
  for (let i = 1; i <= total; i++) {
    onProgress?.({
      phase: 'rendering',
      current: i,
      total,
      message: `渲染第 ${i}/${total} 页…`,
    })
    pages.push(
      await renderPdfPageDocument({
        doc,
        pageNumber: i,
        label,
        totalPages: total,
      }),
    )
  }

  try {
    const closable = doc as { destroy?: () => Promise<void> }
    await closable.destroy?.()
  } catch {
    /* ignore */
  }

  onProgress?.({
    phase: 'done',
    current: total,
    total,
    message: `已导入 ${total} 页`,
  })

  return { pages, connections: [], label }
}

/**
 * 语料包：已完成的 layout/OCR + 页图 + A1，可导出后再导入，跳过重渲/重 OCR。
 */

import type { PageDocument, PageTextChunk } from '../zigzag/types'
import type { OcrPageResult, OcrBlock } from './ocrService'
import { imageUrlToDataUri } from './ocrService'
import type { BookIndex, AChunk } from '../reasoning/pipelineA'
import type { BookSemanticIndex } from '../reasoning/semanticIndex'
import { downloadTextFile } from '../reasoning/a1DsExport'

export const CORPUS_PACK_KIND = 'docuverse-corpus' as const
export const CORPUS_PACK_VERSION = 1 as const

export type CorpusPackPage = {
  strandIndex: number
  title: string
  text: string
  sourceDoc?: string
  sourcePage?: number
  textChunks?: PageTextChunk[]
  /** jpeg/png data URI — 有则下次无需重渲 */
  imageDataUri?: string
}

export type CorpusPack = {
  kind: typeof CORPUS_PACK_KIND
  version: typeof CORPUS_PACK_VERSION
  label: string
  docId: string
  exportedAt: number
  bookIndex: BookIndex
  ocrByStrand: Record<string, OcrPageResult>
  semanticIndex: BookSemanticIndex | null
  pages: CorpusPackPage[]
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v !== 'null' && typeof v === 'object' && v !== null
}

function dataUriToObjectUrl(dataUri: string): string {
  const m = /^data:([^;,]+)?(;base64)?,(.*)$/s.exec(dataUri)
  if (!m) throw new Error('无效 imageDataUri')
  const mime = m[1] || 'image/jpeg'
  const isB64 = Boolean(m[2])
  const data = m[3] || ''
  let bytes: Uint8Array
  if (isB64) {
    const bin = atob(data)
    bytes = new Uint8Array(bin.length)
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
  } else {
    const decoded = decodeURIComponent(data)
    bytes = new TextEncoder().encode(decoded)
  }
  return URL.createObjectURL(new Blob([bytes], { type: mime }))
}

export async function buildCorpusPack(input: {
  label: string
  docId: string
  bookIndex: BookIndex
  ocrByStrand: Record<number, OcrPageResult>
  semanticIndex: BookSemanticIndex | null
  pages: PageDocument[]
  /** 默认 true：写入页图以便下次免渲染 */
  includeImages?: boolean
}): Promise<CorpusPack> {
  const includeImages = input.includeImages !== false
  const pages: CorpusPackPage[] = []
  for (const p of input.pages) {
    let imageDataUri: string | undefined
    if (includeImages && p.imageUrl) {
      try {
        imageDataUri = await imageUrlToDataUri(p.imageUrl)
      } catch {
        imageDataUri = undefined
      }
    }
    pages.push({
      strandIndex: p.strandIndex,
      title: p.title,
      text: p.text,
      sourceDoc: p.sourceDoc,
      sourcePage: p.sourcePage,
      textChunks: p.textChunks,
      imageDataUri,
    })
  }

  const ocrByStrand: Record<string, OcrPageResult> = {}
  for (const [k, v] of Object.entries(input.ocrByStrand)) {
    ocrByStrand[String(k)] = v
  }

  return {
    kind: CORPUS_PACK_KIND,
    version: CORPUS_PACK_VERSION,
    label: input.label,
    docId: input.docId,
    exportedAt: Date.now(),
    bookIndex: input.bookIndex,
    ocrByStrand,
    semanticIndex: input.semanticIndex,
    pages,
  }
}

export function downloadCorpusPack(pack: CorpusPack): void {
  const slug =
    pack.label.replace(/[^\w\u4e00-\u9fff\-]+/g, '_').slice(0, 48) || 'corpus'
  downloadTextFile(
    `docuverse_${slug}_${pack.exportedAt}.docuverse.json`,
    JSON.stringify(pack),
    'application/json;charset=utf-8',
  )
}

export function parseCorpusPack(raw: unknown): {
  ok: true
  pack: CorpusPack
} | { ok: false; error: string } {
  if (!isRecord(raw)) return { ok: false, error: '不是 JSON 对象' }
  if (raw.kind !== CORPUS_PACK_KIND) {
    return { ok: false, error: '不是 docuverse 语料包' }
  }
  if (raw.version !== CORPUS_PACK_VERSION) {
    return { ok: false, error: `不支持的语料包版本：${String(raw.version)}` }
  }
  if (typeof raw.label !== 'string' || typeof raw.docId !== 'string') {
    return { ok: false, error: '缺少 label/docId' }
  }
  if (!isRecord(raw.bookIndex) || !Array.isArray(raw.bookIndex.chunks)) {
    return { ok: false, error: '缺少有效 bookIndex' }
  }
  if (!Array.isArray(raw.pages)) {
    return { ok: false, error: '缺少 pages' }
  }
  return { ok: true, pack: raw as unknown as CorpusPack }
}

export function corpusPackToRuntime(pack: CorpusPack): {
  label: string
  docId: string
  pages: PageDocument[]
  ocrByStrand: Record<number, OcrPageResult>
  bookIndex: BookIndex
  semanticIndex: BookSemanticIndex | null
} {
  const pages: PageDocument[] = pack.pages.map((p) => {
    let imageUrl: string | undefined
    if (p.imageDataUri) {
      try {
        imageUrl = dataUriToObjectUrl(p.imageDataUri)
      } catch {
        imageUrl = undefined
      }
    }
    return {
      strandIndex: p.strandIndex,
      title: p.title,
      text: p.text,
      offsetMap: [],
      imageUrl,
      sourceDoc: p.sourceDoc ?? 'upload',
      sourcePage: p.sourcePage,
      textChunks: p.textChunks,
    }
  })

  const ocrByStrand: Record<number, OcrPageResult> = {}
  for (const [k, v] of Object.entries(pack.ocrByStrand ?? {})) {
    const n = Number(k)
    if (!Number.isFinite(n) || !v || !Array.isArray(v.blocks)) continue
    ocrByStrand[n] = v
  }

  return {
    label: pack.label,
    docId: pack.docId,
    pages,
    ocrByStrand,
    bookIndex: pack.bookIndex as BookIndex,
    semanticIndex: pack.semanticIndex,
  }
}

/** 轻量校验 blocks，避免坏包拖垮 UI */
export function assertOcrBlocksSane(blocks: OcrBlock[]): boolean {
  return blocks.every(
    (b) =>
      typeof b.id === 'string' &&
      Array.isArray(b.bbox) &&
      b.bbox.length === 4 &&
      typeof b.content === 'string',
  )
}

export function assertBookIndexSane(index: BookIndex): boolean {
  return (
    typeof index.docId === 'string' &&
    Array.isArray(index.chunks) &&
    index.chunks.every(
      (c: AChunk) =>
        typeof c.key === 'string' &&
        typeof c.page === 'number' &&
        Array.isArray(c.bbox),
    )
  )
}

