import { useRef, useState } from 'react'
import { isPublicDemo } from '../demoMode'
import { importPdfFile } from '../data/pdfImport'
import { ingestScannedPdfParallel } from '../data/pdfPagePipeline'
import {
  assertBookIndexSane,
  buildCorpusPack,
  corpusPackToRuntime,
  downloadCorpusPack,
  parseCorpusPack,
} from '../data/corpusPack'
import {
  loadDualModelConfig,
  saveDualModelConfig,
} from '../reasoning/modelRuntimeConfig'
import { useIndexGate } from '../reasoning/indexGate'
import {
  a1DsChatPromptStub,
  exportA1ForDeepSeek,
  exportA1ForDeepSeekJsonl,
} from '../reasoning/a1DsExport'
import { useDocuverse } from '../canvas/store'

export function PdfUploadPanel() {
  const inputRef = useRef<HTMLInputElement>(null)
  const packInputRef = useRef<HTMLInputElement>(null)
  const applyUploadedUniverse = useDocuverse((s) => s.applyUploadedUniverse)
  const clearWorkspaceAnnotations = useDocuverse(
    (s) => s.clearWorkspaceAnnotations,
  )
  const setUploadProgress = useDocuverse((s) => s.setUploadProgress)
  const uploadProgress = useDocuverse((s) => s.uploadProgress)
  const corpus = useDocuverse((s) => s.corpus)
  const uploadLabel = useDocuverse((s) => s.uploadLabel)
  const setImporting = useIndexGate((s) => s.setImporting)
  const finalizeIndex = useIndexGate((s) => s.finalizeIndex)
  const hydrateFromCorpusPack = useIndexGate((s) => s.hydrateFromCorpusPack)
  const setIndexError = useIndexGate((s) => s.setError)
  const resetIndex = useIndexGate((s) => s.reset)
  const indexPhase = useIndexGate((s) => s.phase)
  const indexMessage = useIndexGate((s) => s.message)
  const indexReady = useIndexGate((s) => s.ready)
  const tocStatus = useIndexGate((s) => s.tocStatus)
  const openTocWizard = useIndexGate((s) => s.openTocWizard)
  const semanticIndex = useIndexGate((s) => s.semanticIndex)

  const [error, setError] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)
  const [exportNote, setExportNote] = useState<string | null>(null)
  const [pdfHasTextLayer, setPdfHasTextLayer] = useState(
    () => loadDualModelConfig().pdfHasTextLayer,
  )
  const bookIndex = useIndexGate((s) => s.bookIndex)

  const persistTextLayerFlag = (hasText: boolean) => {
    setPdfHasTextLayer(hasText)
    const cfg = loadDualModelConfig()
    saveDualModelConfig({ ...cfg, pdfHasTextLayer: hasText })
  }

  const onPickPdf = async (file: File | undefined) => {
    if (!file) return
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      setError('请选择 PDF 文件')
      return
    }
    setError(null)
    setBusy(true)
    resetIndex()
    setImporting('正在打开 PDF…')
    try {
      const cfg = loadDualModelConfig()
      const shouldOcr = cfg.autoOcrOnUpload !== false && !pdfHasTextLayer

      if (shouldOcr) {
        // 扫描件：渲一页 → 立刻 emit；多页并行。不先等全书渲染。
        useIndexGate.setState({
          phase: 'ocr',
          message: '并行渲图 + layout/OCR…',
          ready: false,
        })
        const labelGuess = file.name.replace(/\.pdf$/i, '') || 'Uploaded PDF'
        const docId = `upload:${labelGuess}`
        const ingested = await ingestScannedPdfParallel({
          file,
          docId,
          concurrency: 3,
          onProgress: (p) => {
            setUploadProgress({
              current: p.done,
              total: Math.max(p.total, 1),
              message: p.message,
            })
            useIndexGate.setState({
              phase: 'ocr',
              message: p.message,
            })
          },
        })
        applyUploadedUniverse({
          pages: ingested.pages,
          connections: ingested.connections,
          label: ingested.label,
          ocrByStrand: ingested.ocrByStrand,
        })
        if (ingested.failed > 0) {
          setError(
            `部分页面未能识别（${ingested.failed}/${ingested.done + ingested.failed}）· 将使用已有结果继续`,
          )
        }
        setUploadProgress({
          current: 0,
          total: 1,
          message: '正在整理文献…',
        })
        await finalizeIndex({
          docId: `upload:${ingested.label}`,
          pages: ingested.pages,
          ocrByStrand: ingested.ocrByStrand,
        })
      } else {
        // 文字层：顺序渲全书，跳过 OCR
        const result = await importPdfFile(file, (p) => {
          setUploadProgress({
            current: p.current,
            total: p.total,
            message: p.message,
          })
        })
        applyUploadedUniverse(result)
        setUploadProgress({
          current: 0,
          total: 1,
          message: '正在整理文献…',
        })
        const docId = `upload:${result.label}`
        const { pages, ocrByStrand } = useDocuverse.getState()
        await finalizeIndex({ docId, pages, ocrByStrand })
      }
      setUploadProgress(null)
    } catch (e) {
      const msg = e instanceof Error ? e.message : '导入失败'
      setError(msg)
      setIndexError(msg)
      setUploadProgress(null)
    } finally {
      setBusy(false)
      if (inputRef.current) inputRef.current.value = ''
    }
  }

  const onPickPack = async (file: File | undefined) => {
    if (!file) return
    setError(null)
    setBusy(true)
    resetIndex()
    setImporting('正在载入语料包…')
    try {
      const text = await file.text()
      let raw: unknown
      try {
        raw = JSON.parse(text) as unknown
      } catch {
        throw new Error('语料包不是合法 JSON')
      }
      const parsed = parseCorpusPack(raw)
      if (!parsed.ok) throw new Error(parsed.error)
      if (!assertBookIndexSane(parsed.pack.bookIndex)) {
        throw new Error('语料包 bookIndex 损坏')
      }
      const runtime = corpusPackToRuntime(parsed.pack)
      applyUploadedUniverse({
        pages: runtime.pages,
        connections: [],
        label: runtime.label,
        ocrByStrand: runtime.ocrByStrand,
      })
      hydrateFromCorpusPack({
        bookIndex: runtime.bookIndex,
        semanticIndex: runtime.semanticIndex,
      })
      setExportNote(
        `已载入语料包 · ${runtime.bookIndex.chunks.length} 段 · 跳过重渲/重 OCR`,
      )
      setUploadProgress(null)
    } catch (e) {
      const msg = e instanceof Error ? e.message : '语料包载入失败'
      setError(msg)
      setIndexError(msg)
      setUploadProgress(null)
    } finally {
      setBusy(false)
      if (packInputRef.current) packInputRef.current.value = ''
    }
  }

  const onExportCorpusPack = async () => {
    if (!bookIndex) return
    setExportNote('正在打包语料（含页图）…')
    try {
      const { pages, ocrByStrand, uploadLabel: label } = useDocuverse.getState()
      const pack = await buildCorpusPack({
        label: label || bookIndex.docId.replace(/^upload:/, '') || 'corpus',
        docId: bookIndex.docId,
        bookIndex,
        ocrByStrand,
        semanticIndex,
        pages,
        includeImages: true,
      })
      downloadCorpusPack(pack)
      setExportNote(
        `已导出语料包 · ${pack.pages.length} 页 · ${bookIndex.chunks.length} 段（下次可直接载入，免重渲 OCR）`,
      )
    } catch (e) {
      setError(e instanceof Error ? e.message : '导出语料包失败')
      setExportNote(null)
    }
  }

  return (
    <section className="hud-panel upload">
      <h2>上传 PDF</h2>
      {isPublicDemo ? (
        <p className="meta">上传后可在右侧输入问题并对照出处</p>
      ) : (
        <p className="meta">
          扫描件：并行「渲→OCR」全书；就绪后可导出语料包，下次直接载入免重跑
        </p>
      )}
      <label className="meta" style={{ display: 'block', marginBottom: 8 }}>
        <input
          type="checkbox"
          checked={pdfHasTextLayer}
          disabled={busy}
          onChange={(e) => persistTextLayerFlag(e.target.checked)}
        />{' '}
        PDF 有可用文字层（勾选则跳过 OCR，直接用 PDF 文字）
      </label>
      <input
        ref={inputRef}
        type="file"
        accept="application/pdf,.pdf"
        hidden
        onChange={(e) => void onPickPdf(e.target.files?.[0])}
      />
      <input
        ref={packInputRef}
        type="file"
        accept="application/json,.json,.docuverse.json"
        hidden
        onChange={(e) => void onPickPack(e.target.files?.[0])}
      />
      <button
        type="button"
        className="upload-btn"
        disabled={busy}
        onClick={() => inputRef.current?.click()}
      >
        {busy ? '处理中…' : '选择 PDF 文件'}
      </button>
      <button
        type="button"
        className="corpus-chip"
        disabled={busy}
        title="载入此前导出的 .docuverse.json（含 layout/OCR/页图）"
        onClick={() => packInputRef.current?.click()}
      >
        载入语料包
      </button>
      <button
        type="button"
        className="corpus-chip"
        disabled={busy}
        title="清除标注；页面保留"
        onClick={() => {
          if (
            !window.confirm(
              '清除全部强调 / 连线标注？页面会保留，可继续导入。',
            )
          ) {
            return
          }
          clearWorkspaceAnnotations()
          resetIndex()
        }}
      >
        清空标注
      </button>
      {(busy || indexPhase === 'ocr' || indexPhase === 'embedding') && (
        <p className="meta">{indexMessage}</p>
      )}
      {indexReady && (
        <p className="meta" style={{ color: '#5cffb1' }}>
          ✓ {indexMessage}
        </p>
      )}
      {indexReady && bookIndex && (
        <div style={{ marginTop: 8, display: 'flex', flexWrap: 'wrap', gap: 6 }}>
          <button
            type="button"
            className="corpus-chip"
            title="导出完整语料包：A1 + OCR + 页图，下次载入免重渲/重 OCR"
            onClick={() => void onExportCorpusPack()}
          >
            导出语料包
          </button>
          <button
            type="button"
            className="corpus-chip"
            title="导出 Markdown 分包：KEY+原文+强制吐 key 指令，可直接丢给 DeepSeek"
            onClick={() => {
              try {
                const r = exportA1ForDeepSeek(bookIndex)
                setExportNote(
                  r.mode === 'single'
                    ? `已导出 .md · ${r.rowCount} 行 KEY（可直接上传 DS）`
                    : `书过大：错开下载 ${r.packCount} 个 .md 包 · 共 ${r.rowCount} 行（请允许多次下载）`,
                )
              } catch (e) {
                setError(e instanceof Error ? e.message : '导出失败')
              }
            }}
          >
            导出 A1→DS（.md）
          </button>
          <button
            type="button"
            className="corpus-chip"
            title="导出 JSONL 分包（每行 {key,pdfPage,text}）"
            onClick={() => {
              try {
                const r = exportA1ForDeepSeekJsonl(bookIndex)
                setExportNote(
                  r.mode === 'single'
                    ? `已导出 .jsonl · ${r.rowCount} 行`
                    : `错开下载 ${r.packCount} 个 .jsonl · 共 ${r.rowCount} 行`,
                )
              } catch (e) {
                setError(e instanceof Error ? e.message : '导出失败')
              }
            }}
          >
            导出 A1→DS（.jsonl）
          </button>
          <button
            type="button"
            className="corpus-chip"
            title="复制一段可贴进 DeepSeek 对话框的规则+问题壳"
            onClick={() => {
              void navigator.clipboard
                .writeText(a1DsChatPromptStub(''))
                .then(() => setExportNote('已复制 DS 提问壳（规则+空问题）'))
                .catch(() => setError('剪贴板写入失败'))
            }}
          >
            复制 DS 提问壳
          </button>
        </div>
      )}
      {exportNote && (
        <p className="meta" style={{ color: '#9ecbff' }}>
          {exportNote}
        </p>
      )}
      {indexReady && tocStatus === 'pending' && (
        <p className="meta" style={{ color: '#ffcc66' }}>
          目录向导待完成（点选目录页 → toc_map）{' '}
          <button type="button" className="corpus-chip" onClick={() => openTocWizard()}>
            打开向导
          </button>
        </p>
      )}
      {tocStatus === 'skipped' && (
        <p className="meta" style={{ color: '#ff8a8a' }}>
          ⚠ 已跳过目录 · 无 TOC 闭集（提问走全书 BM25）{' '}
          <button type="button" className="corpus-chip" onClick={() => openTocWizard()}>
            重新打开向导
          </button>
        </p>
      )}
      {tocStatus === 'confirmed' && (
        <p className="meta" style={{ color: '#5cffb1' }}>
          ✓ 目录已确认并完成 key 归属
        </p>
      )}
      {uploadProgress && (
        <div className="upload-progress">
          <div className="bar">
            <span
              style={{
                width:
                  uploadProgress.total > 0
                    ? `${Math.min(100, (100 * uploadProgress.current) / uploadProgress.total)}%`
                    : '30%',
              }}
            />
          </div>
          <p className="meta">{uploadProgress.message}</p>
        </div>
      )}
      {error && <p className="error">{error}</p>}
      {corpus === 'upload' && uploadLabel && (
        <p className="meta">当前：{uploadLabel}</p>
      )}
    </section>
  )
}

/**
 * 扫描 PDF：页级流水线 = 渲一页 → 立刻 emit(layout+OCR) → 落账。
 *
 * 调度序（只影响何时开跑，不影响门牌）：
 *   1) 书序头 ~15% ∥ 尾 ~15%（目录常在前或后）
 *   2) 再并行中间
 *
 * bookKey 身份 = (docId, strand/page, layoutK)，按书序坐标铸；
 * 完成先后乱序不改门牌。A1 组装时仍按 strand 排序。
 */

import type { PageDocument, ResolvedConnection } from '../zigzag/types'
import type { OcrPageResult } from './ocrService'
import { imageUrlToDataUri } from './ocrService'
import {
  openPdfDocument,
  renderPdfPageDocument,
  type OpenedPdf,
} from './pdfImport'
import { emitPageViaProtocol } from '../reasoning/emitClient'
import { runBatchesParallel } from '../arch/parallelLlmBatch'

export const PDF_EMIT_CONCURRENCY = 3
/** 与冷启骨架同口径：头/尾各约 15% */
export const INGEST_EDGE_RATIO = 0.15

export type PageEmitProgress = {
  done: number
  total: number
  strand: number
  phase: 'edges' | 'middle' | 'done'
  message: string
}

/**
 * 调度用 strand 列表（0-based）。
 * 去重、不重叠：先头、再尾、再中间。短书自动收缩。
 */
export function scheduleStrandsHeadTailThenMiddle(pageCount: number): {
  head: number[]
  tail: number[]
  middle: number[]
  /** 头∪尾（波 1） */
  edges: number[]
} {
  if (pageCount <= 0) {
    return { head: [], tail: [], middle: [], edges: [] }
  }
  if (pageCount <= 2) {
    const all = Array.from({ length: pageCount }, (_, i) => i)
    return { head: all, tail: [], middle: [], edges: all }
  }
  const n = Math.max(1, Math.ceil(pageCount * INGEST_EDGE_RATIO))
  const head = Array.from({ length: n }, (_, i) => i)
  const tailStart = Math.max(n, pageCount - n)
  const tail = Array.from(
    { length: pageCount - tailStart },
    (_, i) => tailStart + i,
  )
  const middle: number[] = []
  for (let s = n; s < tailStart; s++) middle.push(s)
  return { head, tail, middle, edges: [...head, ...tail] }
}

export async function ingestScannedPdfParallel(input: {
  file: File
  docId: string
  concurrency?: number
  onProgress?: (p: PageEmitProgress) => void
  onPage?: (page: PageDocument, ocr: OcrPageResult) => void
}): Promise<{
  pages: PageDocument[]
  connections: ResolvedConnection[]
  label: string
  ocrByStrand: Record<number, OcrPageResult>
  done: number
  failed: number
  opened: OpenedPdf
}> {
  const opened = await openPdfDocument(input.file, (msg) => {
    input.onProgress?.({
      done: 0,
      total: 0,
      strand: 0,
      phase: 'edges',
      message: msg,
    })
  })
  const { doc, total, label } = opened
  const concurrency = Math.max(1, input.concurrency ?? PDF_EMIT_CONCURRENCY)
  const bands = scheduleStrandsHeadTailThenMiddle(total)

  const pagesSlot: Array<PageDocument | undefined> = Array.from({
    length: total,
  })
  const ocrByStrand: Record<number, OcrPageResult> = {}
  let done = 0
  let failed = 0
  let finished = 0

  const bump = (strand: number, phase: 'edges' | 'middle', bandLabel: string) => {
    finished += 1
    input.onProgress?.({
      done: finished,
      total,
      strand,
      phase,
      message: `${bandLabel} · 并行渲+OCR ${finished}/${total}（成功 ${done} · 失败 ${failed} · 并发≤${concurrency}）`,
    })
  }

  const runWave = async (
    strands: number[],
    phase: 'edges' | 'middle',
    bandLabel: string,
  ) => {
    if (strands.length === 0) return
    // 1-based pdf 页号；队列序 = 调度序，≠ 完成序
    const pageNums = strands.map((s) => s + 1)
    const parallel = await runBatchesParallel({
      batches: pageNums,
      concurrency,
      run: async (pageNum) => {
        const page = await renderPdfPageDocument({
          doc,
          pageNumber: pageNum,
          label,
          totalPages: total,
        })
        if (!page.imageUrl) {
          throw new Error(`页 ${pageNum} 无图像`)
        }
        const dataUri = await imageUrlToDataUri(page.imageUrl)
        // 门牌坐标用 strand，与本波何时跑完无关
        const ocr = await emitPageViaProtocol({
          docId: input.docId,
          page: page.strandIndex,
          strandIndex: page.strandIndex,
          imageDataUri: dataUri,
        })
        pagesSlot[page.strandIndex] = page
        ocrByStrand[page.strandIndex] = ocr
        done += 1
        input.onPage?.(page, ocr)
        bump(page.strandIndex, phase, bandLabel)
        return { page, ocr }
      },
    })

    for (const r of parallel.results) {
      if (r.ok) continue
      failed += 1
      // r.index = 本波队列下标 → 还原真实 strand（不可把 index 当书序）
      const strand = strands[r.index] ?? r.index
      const placeholder: PageDocument = {
        strandIndex: strand,
        title: `${label} p.${strand + 1}（识别失败）`,
        text: `${label}\nPage ${strand + 1}\n(emit failed)`,
        offsetMap: [],
        sourceDoc: 'upload',
        sourcePage: strand + 1,
        textChunks: [],
      }
      if (!pagesSlot[strand]) pagesSlot[strand] = placeholder
      bump(strand, phase, bandLabel)
    }
  }

  await runWave(
    bands.edges,
    'edges',
    `头尾各~${Math.round(INGEST_EDGE_RATIO * 100)}%`,
  )
  await runWave(bands.middle, 'middle', '中间页')

  try {
    const closable = doc as { destroy?: () => Promise<void> }
    await closable.destroy?.()
  } catch {
    /* ignore */
  }

  // 按书序补槽（0…total-1），不按完成先后
  for (let i = 0; i < total; i++) {
    if (!pagesSlot[i]) {
      pagesSlot[i] = {
        strandIndex: i,
        title: `${label} p.${i + 1}（缺失）`,
        text: `${label}\nPage ${i + 1}`,
        offsetMap: [],
        sourceDoc: 'upload',
        sourcePage: i + 1,
        textChunks: [],
      }
    }
  }

  input.onProgress?.({
    done: total,
    total,
    strand: Math.max(0, total - 1),
    phase: 'done',
    message: `全书处理完毕 · 成功 ${done}/${total}（门牌按书序 strand，非完成序）`,
  })

  return {
    pages: pagesSlot as PageDocument[],
    connections: [],
    label,
    ocrByStrand,
    done,
    failed,
    opened,
  }
}

/**
 * 语料包页图金库：瘦载入时只存 data URI，审计 bookKey 时再解码成 blob URL。
 * 与书序无关；按 strand 调取。
 */

const vault = new Map<number, string>()

export function clearPageImageVault(): void {
  vault.clear()
}

export function stashPageImageDataUri(
  strand: number,
  dataUri: string | undefined,
): void {
  if (strand < 0) return
  if (!dataUri || !dataUri.startsWith('data:')) {
    vault.delete(strand)
    return
  }
  vault.set(strand, dataUri)
}

export function stashPageImagesFromPack(
  pages: Array<{ strandIndex: number; imageDataUri?: string }>,
): number {
  let n = 0
  for (const p of pages) {
    if (p.imageDataUri?.startsWith('data:')) {
      vault.set(p.strandIndex, p.imageDataUri)
      n += 1
    }
  }
  return n
}

export function peekPageImageDataUri(strand: number): string | undefined {
  return vault.get(strand)
}

export function hasPageImageInVault(strand: number): boolean {
  return vault.has(strand)
}

export function vaultSize(): number {
  return vault.size
}

/** data URI → blob: URL（调用方负责 revoke 旧链） */
export function dataUriToObjectUrl(dataUri: string): string {
  const m = /^data:([^;,]+)?(;base64)?,(.*)$/s.exec(dataUri)
  if (!m) throw new Error('无效 imageDataUri')
  const mime = m[1] || 'image/jpeg'
  const isB64 = Boolean(m[2])
  const data = m[3] || ''
  let bytes: Uint8Array
  if (isB64) {
    const bin = atob(data)
    bytes = new Uint8Array(bin.length)
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
  } else {
    bytes = new TextEncoder().encode(decodeURIComponent(data))
  }
  return URL.createObjectURL(new Blob([bytes], { type: mime }))
}

/**
 * 从金库物化一页图。成功则仍保留 data URI（可再物化）；不删除金库。
 */
export function materializePageImageFromVault(strand: number): {
  ok: true
  imageUrl: string
} | { ok: false; note: string } {
  const dataUri = vault.get(strand)
  if (!dataUri) {
    return { ok: false, note: `金库无 strand=${strand} 页图` }
  }
  try {
    return { ok: true, imageUrl: dataUriToObjectUrl(dataUri) }
  } catch (e) {
    return {
      ok: false,
      note: e instanceof Error ? e.message : '页图解码失败',
    }
  }
}

