  })

  const ocrByStrand: Record<number, OcrPageResult> = {}
  for (const [k, v] of Object.entries(pack.ocrByStrand ?? {})) {
    const n = Number(k)
    if (!Number.isFinite(n) || !v || !Array.isArray(v.blocks)) continue
    ocrByStrand[n] = v
  }

  return {
    label: pack.label,
    docId: pack.docId,
